-- =============================================================================================
-- BizApps Committees v1.5.x -- Metadata_Sync (one per release)
-- =============================================================================================
-- Generated by `mj sync push --dir metadata --ci` (MJ CLI 6.1.6) with sqlLogging on, against a
-- database built from migrations ONLY: MJ core v6.1.6, bizapps-common v5.56.0, bizapps-tasks
-- v1.10.0, then this app's migrations at `next`. Push result: 7 created, 1 updated, 109 unchanged,
-- 0 errors.
--
-- WHAT THIS CARRIES (the metadata/ changes since v1.4.0):
--   * MJ: Row Level Security Filters -- "Committees: Visible Votes" created (ballot sealing, C0).
--   * MJ: Entity Permissions -- UI role on Committees: Votes: read only, through that filter.
--   * MJ: Record Processes -- the weekly Quorum Risk scoring process for Committees: Meetings.
--   * MJ: ML Training Pipelines -- "Predict Meeting Quorum Risk".
--   * MJ: ML Models -- its three Draft models (versions 1-3; no artifact file).
--   * MJ: ML Model Scoring Bindings -- version 1 -> Meetings.PredictedQuorumRiskProbability.
--
-- NOT INCLUDED: the "Record Process: Score Committees: Meetings ... (Weekly)" Scheduled Job the
-- push also wrote. It is not declared in metadata/: MJ's RecordProcess server entity creates it as a
-- side effect when a record process is saved through the entity layer, and it is Active, so seeding
-- it would switch on weekly scoring with Draft models on every host. A host gets it the first time
-- the record process is saved in the app.
--
-- TRANSFORMS (as in V202609181200): the logger writes `${flyway:defaultSchema}` for the MJ core
-- schema; in an open app that placeholder is the app's own schema, so every call here (all are core
-- procedures) and the core view names inside the filter's FilterText use `${mjSchema}` instead
-- (metadata/ has `[__mj]` there). App and Common schema names in FilterText stay literal.
--
-- GUARDS, so a host that already ran `mj sync push` of this metadata is not broken (idempotent):
--   * Every create is skipped when its ID already exists (none of these tables has a unique key
--     beyond the ID); the filter is also matched on Name, which is how the permission finds it.
--   * The permission row is keyed by EntityID + RoleID + Type (UQ_EntityPermission_EntityID_RoleID_Type).
--     Its ID was generated at install time, so the update re-resolves it on the host; a second block
--     creates the row only when the host has none. The UI role and the filter are re-resolved by name.
--   * No record here is created by an earlier migration (the push created all seven on a database
--     built from every migration, including V202609181200).
--
-- GENERATION-ONLY STEP: on a clean MJ 6.1.6 database no role may create MJ: Row Level Security
-- Filters, so the push (run as System) was refused. The Developer role was granted CanCreate /
-- CanUpdate on that entity in the generation database only; that grant is not part of this file.
--
-- Proved on a second database built the same way, the full chain including this file.
-- =============================================================================================

-- Save MJ: Row Level Security Filters (core SP call only)
DECLARE @ID_0a1b1f845dd2 UNIQUEIDENTIFIER,
@Name_0a1b1f845dd2 NVARCHAR(100),
@Description_0a1b1f845dd2 NVARCHAR(MAX),
@FilterText_0a1b1f845dd2 NVARCHAR(MAX)
SET
  @ID_0a1b1f845dd2 = '6C0B4F2A-9D3E-4B7A-8E51-2F7D9A1C3B64'
SET
  @Name_0a1b1f845dd2 = N'Committees: Visible Votes'
SET
  @Description_0a1b1f845dd2 = N'A vote the caller cast (their Person holds the membership), every vote on a motion that has no ballot (roll calls taken in a meeting), and every vote on a ballot that is Closed or Cancelled and not sealed. A sealed ballot never shows another member''s choice, in any status. The caller''s Person is the user''s own People link (LinkedEntityRecordID, when LinkedEntityID is People or a subtype of it), else the Person whose deprecated LinkedUserID names the user. Parenthesised so it ANDs onto any other filter the caller holds.'
SET
  @FilterText_0a1b1f845dd2 = N'(MembershipID IN (SELECT m.ID FROM [__mj_BizAppsCommittees].[vwMemberships] m WHERE m.PersonID IN (SELECT TRY_CAST(u.LinkedEntityRecordID AS UNIQUEIDENTIFIER) FROM [${mjSchema}].[vwUsers] u WHERE u.ID = TRY_CAST(''{{UserID}}'' AS UNIQUEIDENTIFIER) AND u.LinkedEntityID IN (SELECT e.ID FROM [${mjSchema}].[vwEntities] e WHERE e.Name = N''MJ_BizApps_Common: People'' OR e.ParentID IN (SELECT pe.ID FROM [${mjSchema}].[vwEntities] pe WHERE pe.Name = N''MJ_BizApps_Common: People'')))) OR MembershipID IN (SELECT m.ID FROM [__mj_BizAppsCommittees].[vwMemberships] m INNER JOIN [__mj_BizAppsCommon].[vwPeople] p ON p.ID = m.PersonID WHERE p.LinkedUserID = TRY_CAST(''{{UserID}}'' AS UNIQUEIDENTIFIER)) OR MotionID NOT IN (SELECT b.MotionID FROM [__mj_BizAppsCommittees].[vwBallots] b WHERE b.MotionID IS NOT NULL) OR MotionID IN (SELECT b.MotionID FROM [__mj_BizAppsCommittees].[vwBallots] b WHERE b.Status IN (N''Closed'', N''Cancelled'') AND b.IsSealed = 0))'
IF NOT EXISTS (SELECT 1 FROM [${mjSchema}].[RowLevelSecurityFilter]
               WHERE [ID] = @ID_0a1b1f845dd2
                  OR ([Name] = @Name_0a1b1f845dd2))
EXEC [${mjSchema}].spCreateRowLevelSecurityFilter @ID = @ID_0a1b1f845dd2,
  @Name = @Name_0a1b1f845dd2,
  @Description = @Description_0a1b1f845dd2,
  @FilterText = @FilterText_0a1b1f845dd2;

GO

